/bin/bash -lc "python3 - <<'PY'
import urllib.request, concurrent.futures
base='https://raw.githubusercontent.com/NVIDIA/cuda-samples/db3eea23946bca2e90a75eca2b5b3e07158a9e11/'
paths=['Samples/5_Domain_Specific/MonteCarloMultiGPU/'+f for f in ['MonteCarloMultiGPU.cpp','MonteCarlo_kernel.cu','CMakeLists.txt','MonteCarlo_common.h']]
def fetch(p):
 try:
  s=urllib.request.urlopen(base+p,timeout=30).read().decode()
  return p,s
 except Exception as e:return p,str(e)
for p,s in concurrent.futures.ThreadPoolExecutor().map(fetch,paths):
 print(p)
 if p.endswith('MonteCarloMultiGPU.cpp'):
  lines=s.splitlines(); print('\\n'.join(f'{i+1}: {v}' for i,v in enumerate(lines) if 50<=i+1<=195 or 260<=i+1<=340 or 410<=i+1<=490))
 else:print(s)
PY"

